//! Rust emission.
//!
//! The output is written to be **read**: one `#[repr(C)]` mirror per C typedef
//! with a per-field provenance comment (`header:line`), a generator-computed
//! `LAYOUT` table, a `RUSTC_OFFSETS` table built with `offset_of!`, and a
//! `const` block that fails the *build* if the two disagree. A reviewer can put
//! the header and the generated file side by side and check them line for line;
//! that is the property a bindgen blob does not have.
//!
//! Nothing emitted here relaxes `unsafe_code`. Decoding is byte-slice reads with
//! `from_le_bytes`, so the crate's `#![forbid(unsafe_code)]` holds and the
//! `#[repr(C)]` types are never transmuted — they exist as the *layout oracle*
//! and as the decoded value, never as a cast target.

use crate::ctype::Layout;
use std::fmt::Write as _;

/// Emit the full Rust module text for a set of laid-out structs plus constants.
#[must_use]
pub fn module(
    module_doc: &str,
    ogkm_version: &str,
    layouts: &[Layout],
    consts: &[(String, String, String, String)],
) -> String {
    let mut s = String::new();
    let _ = writeln!(s, "// @generated by kayfabe-abi-gen — DO NOT EDIT BY HAND.");
    let _ = writeln!(s, "//");
    let _ = writeln!(
        s,
        "// Source: open-gpu-kernel-modules {ogkm_version}. Regenerate with:"
    );
    let _ = writeln!(
        s,
        "//   cargo run --manifest-path crates/kayfabe-abi/gen/Cargo.toml -- <ogkm-root> \\"
    );
    let _ = writeln!(s, "//       crates/kayfabe-abi/src/generated");
    let _ = writeln!(s, "//");
    let _ = writeln!(
        s,
        "// Every struct below is a #[repr(C)] MIRROR of the C typedef named in its doc"
    );
    let _ = writeln!(
        s,
        "// comment. `LAYOUT` is the generator's own layout computation; `RUSTC_OFFSETS`"
    );
    let _ = writeln!(
        s,
        "// is rustc's, via `offset_of!`. The `const` block after each struct asserts they"
    );
    let _ = writeln!(
        s,
        "// agree, so a layout bug is a BUILD failure, not a runtime surprise."
    );
    let _ = writeln!(s);
    for line in module_doc.lines() {
        let _ = writeln!(s, "//! {line}");
    }
    let _ = writeln!(s);
    // Import exactly the readers this module uses — an unused import is a
    // warning, and CI runs clippy with `-D warnings`.
    let mut readers: Vec<&str> = layouts
        .iter()
        .flat_map(|l| l.fields.iter().map(|f| f.scalar.prim))
        .collect();
    readers.sort_unstable();
    readers.dedup();
    let mut names: Vec<String> = vec!["AbiError".into()];
    if !layouts.is_empty() {
        names.push("Field".into());
        names.push("StructLayout".into());
    }
    names.extend(readers.iter().map(|p| format!("{p}_at")));
    let _ = writeln!(s, "use crate::wire::{{{}}};", names.join(", "));
    let _ = writeln!(s);

    for (name, ty, value, doc) in consts {
        for l in doc.lines() {
            let _ = writeln!(s, "/// {l}");
        }
        let _ = writeln!(s, "pub const {name}: {ty} = {value};");
        let _ = writeln!(s);
    }

    for l in layouts {
        s.push_str(&one_struct(l));
    }

    // Enumeration surface: the generated table IS the coverage report
    // (`mode2_abi_agnostic_layer.md` §2.3 rule 2).
    let _ = writeln!(
        s,
        "/// Every struct this module generates, in declaration order — the enumerated-vs-"
    );
    let _ = writeln!(
        s,
        "/// exercised coverage surface (`mode2_abi_agnostic_layer.md` §2.3, rule 2)."
    );
    let _ = writeln!(s, "pub const STRUCTS: &[&StructLayout] = &[");
    for l in layouts {
        let _ = writeln!(s, "    &{}::LAYOUT,", l.rust_name);
    }
    let _ = writeln!(s, "];");
    let _ = writeln!(s);
    let _ = writeln!(
        s,
        "/// The generator-computed offsets paired with rustc's own, per struct. The"
    );
    let _ = writeln!(
        s,
        "/// crate's tests walk this so the agreement is also a RUNTIME assertion the"
    );
    let _ = writeln!(s, "/// mutation gate can see.");
    let _ = writeln!(
        s,
        "pub const RUSTC_OFFSETS: &[(&str, &[(&str, usize)])] = &["
    );
    for l in layouts {
        let _ = writeln!(s, "    ({:?}, {}::RUSTC_OFFSETS),", l.c_name, l.rust_name);
    }
    let _ = writeln!(s, "];");

    s
}

fn rust_field_ty(f: &crate::ctype::Field) -> String {
    match f.array_len {
        Some(n) => format!("[{}; {}]", f.scalar.rust, n),
        None => f.scalar.rust.to_string(),
    }
}

#[allow(clippy::too_many_lines)]
fn one_struct(l: &Layout) -> String {
    let mut s = String::new();
    let name = &l.rust_name;

    let _ = writeln!(s, "/// `{}` — ogkm `{}:{}`.", l.c_name, l.header, l.line);
    if let Some(tail) = &l.flexible_tail {
        let _ = writeln!(s, "///");
        let _ = writeln!(
            s,
            "/// The C declaration ends in a flexible array member `{tail}[]`, which occupies"
        );
        let _ = writeln!(
            s,
            "/// no space in `sizeof` and is NOT mirrored here: the trailing payload is the"
        );
        let _ = writeln!(
            s,
            "/// caller's byte slice from offset [`Self::SIZE`] onward."
        );
    }
    // `Default` is derivable only while every array is short enough for std's
    // `[T; N]: Default` impls; `char processName[100]` is not, so that one gets a
    // written-out impl (which clippy accepts precisely because it is *not*
    // derivable).
    let derivable_default = l.fields.iter().all(|f| f.array_len.is_none_or(|n| n <= 32));
    let _ = writeln!(s, "#[repr(C)]");
    if derivable_default {
        let _ = writeln!(s, "#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]");
    } else {
        let _ = writeln!(s, "#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
    }
    let _ = writeln!(s, "pub struct {name} {{");
    for f in &l.fields {
        let arr = match f.array_len {
            Some(n) => format!("[{n}]"),
            None => String::new(),
        };
        let _ = writeln!(
            s,
            "    /// `{} {}{}` @ +{} ({}:{}).",
            f.scalar.c_name, f.c_name, arr, f.offset, l.header, f.line
        );
        let _ = writeln!(s, "    pub {}: {},", f.rust_name, rust_field_ty(f));
    }
    let _ = writeln!(s, "}}");
    let _ = writeln!(s);

    if !derivable_default {
        let _ = writeln!(
            s,
            "// Written out because `[u8; N]: Default` does not hold for every N in std."
        );
        let _ = writeln!(s, "impl Default for {name} {{");
        let _ = writeln!(s, "    fn default() -> Self {{");
        let _ = writeln!(s, "        Self {{");
        for f in &l.fields {
            let v = match f.array_len {
                Some(n) => format!("[0; {n}]"),
                None => "0".to_string(),
            };
            let _ = writeln!(s, "            {}: {v},", f.rust_name);
        }
        let _ = writeln!(s, "        }}");
        let _ = writeln!(s, "    }}");
        let _ = writeln!(s, "}}");
        let _ = writeln!(s);
    }

    let _ = writeln!(s, "impl {name} {{");
    let _ = writeln!(s, "    /// The C typedef name.");
    let _ = writeln!(s, "    pub const C_NAME: &'static str = {:?};", l.c_name);
    let _ = writeln!(
        s,
        "    /// `sizeof({})`, generator-computed and asserted against rustc below.",
        l.c_name
    );
    let _ = writeln!(s, "    pub const SIZE: usize = {};", l.size);
    let _ = writeln!(s, "    /// `alignof({})`.", l.c_name);
    let _ = writeln!(s, "    pub const ALIGN: usize = {};", l.align);
    let _ = writeln!(s, "    /// The generator's field-by-field layout.");
    let _ = writeln!(s, "    pub const LAYOUT: StructLayout = StructLayout {{");
    let _ = writeln!(s, "        c_name: {:?},", l.c_name);
    let _ = writeln!(s, "        size: {},", l.size);
    let _ = writeln!(s, "        align: {},", l.align);
    let _ = writeln!(s, "        fields: &[");
    for f in &l.fields {
        let _ = writeln!(
            s,
            "            Field {{ c_name: {:?}, rust_name: {:?}, offset: {}, width: {} }},",
            f.c_name, f.rust_name, f.offset, f.width
        );
    }
    let _ = writeln!(s, "        ],");
    let _ = writeln!(s, "    }};");
    let _ = writeln!(s);
    let _ = writeln!(
        s,
        "    /// rustc's own offsets for the same fields, in the same order."
    );
    let _ = writeln!(
        s,
        "    pub const RUSTC_OFFSETS: &'static [(&'static str, usize)] = &["
    );
    for f in &l.fields {
        let _ = writeln!(
            s,
            "        ({:?}, core::mem::offset_of!({name}, {})),",
            f.rust_name, f.rust_name
        );
    }
    let _ = writeln!(s, "    ];");
    let _ = writeln!(s);

    // decode
    let _ = writeln!(
        s,
        "    /// Decode from a little-endian byte image of `{}`.",
        l.c_name
    );
    let _ = writeln!(s, "    ///");
    let _ = writeln!(
        s,
        "    /// Accepts a buffer of at least [`Self::SIZE`] bytes and ignores anything"
    );
    let _ = writeln!(
        s,
        "    /// past it (a longer buffer is a legitimate newer-ABI image, or a flexible"
    );
    let _ = writeln!(
        s,
        "    /// array tail). A SHORTER buffer is refused loudly — silently zero-extending"
    );
    let _ = writeln!(
        s,
        "    /// a truncated struct is the `abi_struct_truncation` bug class verbatim."
    );
    let _ = writeln!(s, "    ///");
    let _ = writeln!(s, "    /// # Errors");
    let _ = writeln!(s, "    ///");
    let _ = writeln!(
        s,
        "    /// [`AbiError::Truncated`] if `bytes.len() < Self::SIZE`."
    );
    let _ = writeln!(
        s,
        "    pub fn decode(bytes: &[u8]) -> Result<Self, AbiError> {{"
    );
    let _ = writeln!(s, "        if bytes.len() < Self::SIZE {{");
    let _ = writeln!(s, "            return Err(AbiError::Truncated {{");
    let _ = writeln!(s, "                c_name: Self::C_NAME,");
    let _ = writeln!(s, "                need: Self::SIZE,");
    let _ = writeln!(s, "                got: bytes.len(),");
    let _ = writeln!(s, "            }});");
    let _ = writeln!(s, "        }}");
    let _ = writeln!(s, "        Ok(Self {{");
    for f in &l.fields {
        match f.array_len {
            Some(n) => {
                let _ = writeln!(s, "            {}: {{", f.rust_name);
                let _ = writeln!(s, "                let mut a = [0{}; {n}];", f.scalar.rust);
                let _ = writeln!(
                    s,
                    "                for (i, slot) in a.iter_mut().enumerate() {{"
                );
                let stride = if f.scalar.size == 1 {
                    "i".to_string()
                } else {
                    format!("i * {}", f.scalar.size)
                };
                let _ = writeln!(
                    s,
                    "                    *slot = {}_at(bytes, {} + {stride})?;",
                    f.scalar.prim, f.offset
                );
                let _ = writeln!(s, "                }}");
                let _ = writeln!(s, "                a");
                let _ = writeln!(s, "            }},");
            }
            None => {
                let _ = writeln!(
                    s,
                    "            {}: {}_at(bytes, {})?,",
                    f.rust_name, f.scalar.prim, f.offset
                );
            }
        }
    }
    let _ = writeln!(s, "        }})");
    let _ = writeln!(s, "    }}");
    let _ = writeln!(s);

    // encode_into
    let _ = writeln!(
        s,
        "    /// Write this value back over a little-endian byte image, in place."
    );
    let _ = writeln!(s, "    ///");
    let _ = writeln!(
        s,
        "    /// Writes **only** the declared fields; padding bytes and any trailing"
    );
    let _ = writeln!(
        s,
        "    /// payload are left exactly as found. That is deliberate: the C-era"
    );
    let _ = writeln!(
        s,
        "    /// `writeback_bug_pattern` was a sanitizer that rewrote a whole struct and"
    );
    let _ = writeln!(
        s,
        "    /// so handed CUDA its own scratch state back. A writer that cannot touch a"
    );
    let _ = writeln!(s, "    /// byte it does not name cannot reproduce it.");
    let _ = writeln!(s, "    ///");
    let _ = writeln!(s, "    /// # Errors");
    let _ = writeln!(s, "    ///");
    let _ = writeln!(
        s,
        "    /// [`AbiError::Truncated`] if `bytes.len() < Self::SIZE`."
    );
    let _ = writeln!(
        s,
        "    pub fn encode_into(&self, bytes: &mut [u8]) -> Result<(), AbiError> {{"
    );
    let _ = writeln!(s, "        let len = bytes.len();");
    let _ = writeln!(s, "        if len < Self::SIZE {{");
    let _ = writeln!(s, "            return Err(AbiError::Truncated {{");
    let _ = writeln!(s, "                c_name: Self::C_NAME,");
    let _ = writeln!(s, "                need: Self::SIZE,");
    let _ = writeln!(s, "                got: len,");
    let _ = writeln!(s, "            }});");
    let _ = writeln!(s, "        }}");
    for f in &l.fields {
        match f.array_len {
            Some(_) => {
                let _ = writeln!(
                    s,
                    "        for (i, v) in self.{}.iter().enumerate() {{",
                    f.rust_name
                );
                let _ = writeln!(s, "            let src = v.to_le_bytes();");
                let stride = if f.scalar.size == 1 {
                    "i".to_string()
                } else {
                    format!("i * {}", f.scalar.size)
                };
                let _ = writeln!(s, "            let at = {} + {stride};", f.offset);
                let _ = writeln!(
                    s,
                    "            bytes.get_mut(at..at + {}).ok_or(AbiError::Truncated {{",
                    f.scalar.size
                );
                let _ = writeln!(s, "                c_name: Self::C_NAME,");
                let _ = writeln!(s, "                need: Self::SIZE,");
                let _ = writeln!(s, "                got: len,");
                let _ = writeln!(s, "            }})?.copy_from_slice(&src);");
                let _ = writeln!(s, "        }}");
            }
            None => {
                let _ = writeln!(s, "        {{");
                let _ = writeln!(
                    s,
                    "            let src = self.{}.to_le_bytes();",
                    f.rust_name
                );
                let _ = writeln!(
                    s,
                    "            bytes.get_mut({}..{}).ok_or(AbiError::Truncated {{",
                    f.offset,
                    f.offset + f.width
                );
                let _ = writeln!(s, "                c_name: Self::C_NAME,");
                let _ = writeln!(s, "                need: Self::SIZE,");
                let _ = writeln!(s, "                got: len,");
                let _ = writeln!(s, "            }})?.copy_from_slice(&src);");
                let _ = writeln!(s, "        }}");
            }
        }
    }
    let _ = writeln!(s, "        Ok(())");
    let _ = writeln!(s, "    }}");
    let _ = writeln!(s, "}}");
    let _ = writeln!(s);

    // The build-time cross-check.
    let _ = writeln!(
        s,
        "// The generator's layout vs rustc's, asserted at COMPILE time."
    );
    let _ = writeln!(s, "const _: () = {{");
    let _ = writeln!(
        s,
        "    assert!(core::mem::size_of::<{name}>() == {name}::SIZE);"
    );
    let _ = writeln!(
        s,
        "    assert!(core::mem::align_of::<{name}>() == {name}::ALIGN);"
    );
    for f in &l.fields {
        let _ = writeln!(
            s,
            "    assert!(core::mem::offset_of!({name}, {}) == {});",
            f.rust_name, f.offset
        );
    }
    let _ = writeln!(s, "}};");
    let _ = writeln!(s);

    s
}
